import React, { useState } from 'react';
import styles from "./Counter.module.css";

const Counter = () => {
  const [count, setCount] = useState(0);

  const increment = () => {
    setCount(count + 1);
  };

  const decrement = () => {
    setCount(count - 1);
  };

  const reset = () => {
    setCount(0);
  };

  return (
    <div className={styles.container}>
      <p className={styles.count}>{count}</p>
      <div className={styles.buttons}>
        <button className={styles.button} onClick={increment}>Increment</button>
        <button className={styles.button} onClick={decrement}>Decrement</button>
        <button className={styles.button} onClick={reset}>Reset</button>
      </div>
    </div>
  );
};

export default Counter;

import { useState, useEffect, useRef } from 'react';

interface UseFetchResult<T> {
  data: T | undefined;
  loading: boolean;
  error: Error | undefined;
}

function useFetch<T>(url: string | null): UseFetchResult<T> {
  const [data, setData] = useState<T | undefined>(undefined);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<Error | undefined>(undefined);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (!url) {
      setData(undefined);
      setLoading(false);
      setError(undefined);
      return;
    }

    abortControllerRef.current = new AbortController();

    const fetchData = async () => {
      setLoading(true);
      setError(undefined);

      try {
        const response = await fetch(url, {
          signal: abortControllerRef.current?.signal,
        });

        if (!response.ok) {
          throw new Error(`HTTP error! Status: ${response.status}`);
        }

        const json: T = await response.json();
        setData(json);
      } catch (e: any) {
        if (e.name === 'AbortError') {
          // Request was aborted, do nothing
          console.log('Fetch aborted');
        } else {
          setError(e instanceof Error ? e : new Error("An unknown error occurred."));
        }
      } finally {
        setLoading(false);
      }
    };

    fetchData();

    return () => {
      abortControllerRef.current?.abort();
    };
  }, [url]);

  return { data, loading, error };
}

export { useFetch };

import React, { useReducer } from 'react';

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

interface State {
  todos: Todo[];
  filter: 'all' | 'active' | 'completed';
}

const todoReducer = (state: State, action: {
  type: string;
  payload?: any;
}) => {
  switch (action.type) {
    case 'ADD':
      return {
        ...state,
        todos: [...state.todos, { id: Math.random(), text: action.payload, completed: false }],
        filter: state.filter,
      };
    case 'TOGGLE':
      return {
        ...state,
        todos: state.todos.map(todo =>
          todo.id === action.payload ? { ...todo, completed: !todo.completed } : todo
        ),
        filter: state.filter,
      };
    case 'DELETE':
      return {
        ...state,
        todos: state.todos.filter(todo => todo.id !== action.payload),
        filter: state.filter,
      };
    case 'SET_FILTER':
      return {
        ...state,
        filter: action.payload,
      };
    default:
      return state;
  }
};

const TodoApp = () => {
  const initialState: State = {
    todos: [],
    filter: 'all',
  };

  const [state, dispatch] = useReducer(todoReducer, initialState);

  const handleAddTodo = (text: string) => {
    dispatch({ type: 'ADD', payload: text });
  };

  const handleToggleTodo = (id: number) => {
    dispatch({ type: 'TOGGLE', payload: id });
  };

  const handleDeleteTodo = (id: number) => {
    dispatch({ type: 'DELETE', payload: id });
  };

  const handleSetFilter = (filter: 'all' | 'active' | 'completed') => {
    dispatch({ type: 'SET_FILTER', payload: filter });
  };

  const visibleTodos = (
    state.filter === 'active'
      ? state.todos.filter(todo => !todo.completed)
      : state.filter === 'completed'
        ? state.todos.filter(todo => todo.completed)
        : state.todos
  );

  return (
    <div>
      <h1>Todo App</h1>
      <input
        type="text"
        placeholder="Add todo"
        onKeyDown={(e) => {
          if (e.key === 'Enter') {
            handleAddTodo(e.target.value);
          }
        }}
      />
      <ul>
        {visibleTodos.map(todo => (
          <li key={todo.id}>
            <input
              type="checkbox"
              checked={todo.completed}
              onChange={() => handleToggleTodo(todo.id)}
            />
            <span style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}>
              {todo.text}
            </span>
            <button onClick={() => handleDeleteTodo(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
      <div>
        <button onClick={() => handleSetFilter('all')}>All</button>
        <button onClick={() => handleSetFilter('active')}>Active</button>
        <button onClick={() => handleSetFilter('completed')}>Completed</button>
      </div>
    </div>
  );
};

export default TodoApp;

import { Request, Response, NextFunction } from 'express';

const API_KEYS = ['valid-api-key-1', 'valid-api-key-2']; // Replace with your actual API keys

export const authMiddleware = (req: Request, res: Response, next: NextFunction) => {
  const Authorization = req.headers.authorization;

  if (!Authorization) {
    return res.status(401).json({
      error: "Authorization header is missing.\n" // Escape newline
    });
  }

  if (!Authorization.startsWith('Bearer ')) {
    return res.status(401).json({
      error: "Invalid authorization header format.  Must be 'Bearer <API_KEY>'.\n" // Escape newline
    });
  }

  const apiKey = Authorization.substring(7);

  if (!API_KEYS.includes(apiKey)) {
    return res.status(401).json({
      error: "Invalid API key.\n" // Escape newline
    });
  }

  next();
};

import { setTimeout, clearTimeout } from 'timers/promises';

interface DebounceOptions<T extends unknown[]> {
  leading?: boolean;
  trailing?: boolean;
  maxWait?: number;
}

interface DebouncedFunction<T extends unknown[]> {
  (...args: T):
    void;
  cancel(): void;
}

function debounce<T extends unknown[]>(func: (...args: T) => void, delay: number, options: DebounceOptions<T> = {}): DebouncedFunction<T> {
  let timeoutId: NodeJS.Timeout | null = null;
  let lastArgs: T | null = null;
  let lastThis: any = null;

  const { leading = false, trailing = true, maxWait = delay } = options;

  const debounced = function (this: any, ...args: T) {
    lastArgs = args;
    lastThis = this;

    if (leading) {
      func.apply(this, args);
    }

    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (trailing && lastArgs) {
        func.apply(lastThis, lastArgs);
        lastArgs = null;
        lastThis = null;
      }
    }, maxWait);
  } as DebouncedFunction<T>;

  debounced.cancel = function () {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
      lastArgs = null;
      lastThis = null;
    }
  };

  return debounced;
}

export { debounce };
